import { jsPDF } from "jspdf";

const ARABIC_REGULAR_BASE64 = "";
const ARABIC_BOLD_BASE64 = "";

export const PDF_FONT_FAMILY = "NotoKufiArabic";

export function registerPdfFonts(doc: jsPDF): void {
  doc.addFileToVFS("NotoKufiArabic-Regular.ttf", ARABIC_REGULAR_BASE64);
  doc.addFileToVFS("NotoKufiArabic-Bold.ttf", ARABIC_BOLD_BASE64);
  doc.addFont("NotoKufiArabic-Regular.ttf", PDF_FONT_FAMILY, "normal");
  doc.addFont("NotoKufiArabic-Bold.ttf", PDF_FONT_FAMILY, "bold");
  doc.setFont(PDF_FONT_FAMILY, "normal");
}
